#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's quoting undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"; fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line). Idempotent. Creates ENV_FILE at mode 0600; writes through a symlink
# and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────
#
# Quiet Check D9: create the hosted demo on Render from render.yaml (docs/deploy-render.md).
# Run from the repo root:  bash scripts/render_setup.sh
# It reads the repo-root .env (PayPal client ID and secret, persona emails) only to put values on
# your clipboard for the Render form, and writes back two public values: HOSTED_BACKEND_URL and
# HOSTED_WEB_URL. It never sends anything anywhere itself.

cd "$(dirname "$0")/.."
REPO_SLUG="vickaul-ai/quiet-check"

# clip KEY: put KEY's value from .env on the clipboard without printing it.
clip() {
  local value; value=$(_existing "$1" || true)
  if [[ -z "$value" ]]; then warn "$1 isn't in $ENV_FILE: type it in yourself"; return; fi
  if command -v pbcopy >/dev/null 2>&1; then
    printf '%s' "$value" | pbcopy
    printf '  %s✓ copied%s %s from %s; paste it into the Render form\n' "$GREEN" "$RESET" "$1" "$ENV_FILE"
  else
    warn "no pbcopy: copy $1 from $ENV_FILE by hand"
  fi
}

TOTAL_STAGES=8

banner "Quiet Check: hosted demo on Render (D9)"

# ── 1 ────────────────────────────────────────────────────────────────────
stage "Check the code is on GitHub and CI is green"
say "Render builds from GitHub main, and the Blueprint deploys only after CI passes"
say "(autoDeployTrigger: checksPass)."
if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
  gh run list --repo "$REPO_SLUG" --branch main --limit 3 || true
else
  open_url "https://github.com/$REPO_SLUG/actions"
fi
step "The newest run on main should be the D9 commit, with a green check."
pause "Press Enter when CI on main is green"

# ── 2 ────────────────────────────────────────────────────────────────────
stage "Anthropic: a key with a \$10 spend limit"
say "The hosted chats are open to strangers, so give Render its own key with a hard cap"
say "(decided with Vic: \$10 for the hosted demo). The web app also rate-limits each visitor."
open_url "https://console.anthropic.com/settings/workspaces"
step "Create a workspace, e.g. 'quietcheck-hosted' (or reuse one you keep for this demo)."
step "In that workspace's Limits, set the monthly spend limit to \$10."
step "Under API keys, create a key in that workspace, named e.g. 'quietcheck-render'."
note "If the console's labels differ, the goal is: a key whose workspace can't spend over \$10."
step "Keep the key on your clipboard or in your password manager for stage 4."
pause "Press Enter when the key exists and the limit is set"

# ── 3 ────────────────────────────────────────────────────────────────────
stage "Render: an API key for Workflows"
say "The backend starts a Render Workflows task run for each approved order, through Render's"
say "API, so it needs an API key (RENDER_API_KEY)."
open_url "https://dashboard.render.com/u/settings#api-keys"
step "Account settings > API Keys > Create API Key. Name it 'quietcheck-backend'."
step "Copy it (it starts with rnd_); Render shows it once. Keep it for stage 4."
pause "Press Enter when you have the key"

# ── 4 ────────────────────────────────────────────────────────────────────
stage "Render: create the Blueprint (this starts the paid services)"
say "Render reads render.yaml and lists 7 resources in the oregon region:"
note "  quietcheck-db (Postgres basic-256mb, \$6/mo)"
note "  quietcheck-backend, quietcheck-web (web, Starter \$7/mo each)"
note "  quietcheck-member-a/b/c (private services, Starter \$7/mo each)"
note "  quietcheck-risk (workflow, billed per second of task runs)"
say "About \$41/month in all. Keep them until Nov 30, 2026 (decided with Vic)."
confirm "Create these paid services now?" || { warn "Stopped before creating anything."; exit 1; }
open_url "https://dashboard.render.com/blueprints"
step "New Blueprint Instance > connect GitHub repo $REPO_SLUG (grant Render access if asked)."
step "Branch main; name the Blueprint 'quietcheck'. Render shows the resources and a form for"
step "the values marked sync: false. Fill them in as below, then press Apply / Deploy Blueprint."
pause "Press Enter when the form is open"
say ""
say "quietcheck-backend:"
clip PAYPAL_CLIENT_ID;     pause "  PAYPAL_CLIENT_ID pasted? Enter for the next value"
clip PAYPAL_CLIENT_SECRET; pause "  PAYPAL_CLIENT_SECRET pasted? Enter"
step "PAYPAL_WEBHOOK_ID: type 'pending' for now; stage 6 creates the hosted webhook."
step "ANTHROPIC_API_KEY: the new key from stage 2."
step "RENDER_API_KEY: the rnd_ key from stage 3."
pause "  Done with the backend? Enter"
say "quietcheck-web:"
clip PAYPAL_CLIENT_ID;     pause "  PAYPAL_CLIENT_ID pasted? Enter"
step "ANTHROPIC_API_KEY: the same key from stage 2."
say "CONSOLE_PASSWORD: a random one, since the console can capture or void payments and the login"
say "has no lockout. Not saved to .env (the local web app reads it and would lock your local console)."
if command -v pbcopy >/dev/null 2>&1 && command -v openssl >/dev/null 2>&1; then
  openssl rand -base64 18 | tr -d '\n' | pbcopy
  printf '  %s✓ copied%s a new 24-character password; paste it into the form AND your private note\n' "$GREEN" "$RESET"
else
  step "Generate one with: openssl rand -base64 18  (24 characters)"
fi
note "  (It goes in the Devpost testing instructions, never the repo.)"
pause "  Done with the web service? Enter"
say "Members (each gets only the email seeded on its own list):"
clip PERSONA_CY_EMAIL;  pause "  quietcheck-member-a PERSONA_CY_EMAIL pasted? Enter"
clip PERSONA_BEN_EMAIL; pause "  quietcheck-member-b PERSONA_BEN_EMAIL pasted? Enter"
clip PERSONA_CY_EMAIL;  pause "  quietcheck-member-c PERSONA_CY_EMAIL pasted? Enter"
command -v pbcopy >/dev/null 2>&1 && printf '' | pbcopy
step "Press Apply. Render creates the database, then builds and deploys each service."
pause "Press Enter once you've applied it"

# ── 5 ────────────────────────────────────────────────────────────────────
stage "Wait for the first deploys"
say "The first builds take a few minutes each. In the Blueprint view, wait until all six"
say "services show Live (the workflow shows its tasks: process_order, run_risk_agent,"
say "wait_for_decision) and the database shows Available."
step "If a build fails, open its Logs, and paste the error into the D9 session."
step "In quietcheck-backend's logs, look for 'risk agent' lines later; for now check the members'"
step "logs each say 'initiators allowed: http://quietcheck-backend-…:8100'."
pause "Press Enter when everything is Live"
step "Copy each public URL from the service page (top left, ends in .onrender.com)."
ask HOSTED_BACKEND_URL "quietcheck-backend URL (https://…onrender.com):"
ask HOSTED_WEB_URL "quietcheck-web URL (https://…onrender.com):"
HOSTED_BACKEND_URL="${HOSTED_BACKEND_URL%/}"; HOSTED_WEB_URL="${HOSTED_WEB_URL%/}"
write_env HOSTED_BACKEND_URL "$HOSTED_BACKEND_URL"
write_env HOSTED_WEB_URL "$HOSTED_WEB_URL"

# ── 6 ────────────────────────────────────────────────────────────────────
stage "PayPal: a webhook for the hosted backend"
say "A second webhook on the same sandbox app (decided with Vic); the ngrok one stays for local"
say "runs. PayPal allows up to 10 webhook URLs per app."
open_url "https://developer.paypal.com/dashboard/applications/sandbox"
step "Open the sandbox app you use for Quiet Check > Webhooks > Add Webhook."
step "Webhook URL: $HOSTED_BACKEND_URL/webhooks/paypal"
command -v pbcopy >/dev/null 2>&1 && printf '%s' "$HOSTED_BACKEND_URL/webhooks/paypal" | pbcopy \
  && note "  (the URL is on your clipboard)"
step "Events, the same 5 as the ngrok webhook: Checkout order approved, Payment authorization"
step "created, Payment authorization voided, Payment capture completed, Customer dispute created."
step "Save, then copy the new webhook's ID from the list."
pause "Press Enter when you have the webhook ID"
open_url "https://dashboard.render.com"
step "quietcheck-backend > Environment > PAYPAL_WEBHOOK_ID > Edit: paste the new ID > Save."
step "Choose 'Save, rebuild, and deploy' (or 'Save and deploy'), and wait for it to go Live."
pause "Press Enter when the backend is Live again"

# ── 7 ────────────────────────────────────────────────────────────────────
stage "Smoke check from outside"
say "What a stranger sees: public routes answer, private ones refuse."
if bash scripts/check_hosted.sh "$HOSTED_BACKEND_URL" "$HOSTED_WEB_URL"; then
  printf '  %s✓ all checks passed%s\n' "$GREEN" "$RESET"
else
  SKIPPED+=("scripts/check_hosted.sh failed: paste its output into the D9 session")
  warn "Some checks failed; paste the output above into the D9 session."
fi
pause "Press Enter to continue"

# ── 8 ────────────────────────────────────────────────────────────────────
stage "Run the three personas on the hosted shop"
say "Acceptance: a stranger runs all three personas from the public URL."
open_url "https://www.sandbox.paypal.com"
step "Log out of the sandbox site between buyers (checkout reuses the last login)."
open_url "$HOSTED_WEB_URL"
step "Ana: 'buy the blue backpack in medium', approve as Ana's buyer -> 'Paid'."
step "Ben: same, as Ben's buyer -> 'Payment on hold for review'."
step "Cy: same, as Cy's buyer -> 'We couldn't complete this order'."
step "Console ($HOSTED_WEB_URL/console, any username + CONSOLE_PASSWORD): each order shows 9/9"
step "verified receipts; the feed shows risk_agent.started with runner render_workflow."
step "Render > quietcheck-risk shows one process_order run per order."
pause "Press Enter when done (note anything odd for the D9 session)"

finish
say "Next: tell the D9 session the results (and paste any errors). Keep the services until"
say "Nov 30, 2026, then suspend or delete them in the Render dashboard."
